  public static void Import(){foreach(var group in new[]{"Hangar","Gear","Derived"})foreach(var file in Directory.GetFiles(Source+"/"+group,"*.png")){string n=Path.GetFileName(file);if(n.Contains("preview")||n.Contains("reconstruction")||n.Contains("sentinel_label")||n=="sentinel_nameplate.png"||n=="weapons_panel_complete.png"||n=="rifle_detail_panel.png")continue;var dest=Target+"/"+group+"/"+n;Directory.CreateDirectory(Path.GetDirectoryName(dest));File.Copy(file,dest,true);AssetDatabase.ImportAsset(dest,ImportAssetOptions.ForceSynchronousImport);var t=(TextureImporter)AssetImporter.GetAtPath(dest);t.textureType=TextureImporterType.Sprite;t.spriteImportMode=SpriteImportMode.Single;t.spritePixelsPerUnit=100;t.sRGBTexture=true;bool weaponProfile=n=="thermal_profile_v1.png"||n=="rail_profile_v1.png";t.mipmapEnabled=weaponProfile;t.alphaSource=TextureImporterAlphaSource.FromInput;t.alphaIsTransparency=true;t.filterMode=weaponProfile?FilterMode.Trilinear:FilterMode.Bilinear;t.wrapMode=TextureWrapMode.Clamp;t.npotScale=TextureImporterNPOTScale.None;t.textureCompression=TextureImporterCompression.Uncompressed;t.maxTextureSize=2048;var st=new TextureImporterSettings();t.ReadTextureSettings(st);st.spriteMeshType=SpriteMeshType.FullRect;st.spriteAlignment=(int)SpriteAlignment.Center;t.SetTextureSettings(st);t.SaveAndReimport();}
   Font("Display","ArialBlack.ttf");Font("Body","ArialRoundedBold.ttf");AssetDatabase.SaveAssets();Debug.Log("MenuFidelityImporter: source pixels imported with static fonts; derived surfaces explicitly identified.");}
  static void Font(string name,string file){string dest=Target+"/Fonts/"+name+".asset";var previous=AssetDatabase.LoadAssetAtPath<TMP_FontAsset>(dest);if(previous!=null&&previous.material!=null&&previous.atlasTextures.Length>0&&previous.atlasTextures[0]!=null)return;if(File.Exists(dest))AssetDatabase.DeleteAsset(dest);string src="Assets/Maze/MenuFidelity/Editor/FontSources/"+file;AssetDatabase.ImportAsset(src,ImportAssetOptions.ForceSynchronousImport);var font=AssetDatabase.LoadAssetAtPath<Font>(src);var a=TMP_FontAsset.CreateFontAsset(font,90,9,GlyphRenderMode.SDFAA,2048,2048,AtlasPopulationMode.Dynamic,false);a.name=name;a.TryAddCharacters(new string(Enumerable.Range(32,95).Select(i=>(char)i).ToArray()),out string missing);if(missing.Length>0)throw new InvalidOperationException("Missing glyphs:"+missing);a.atlasPopulationMode=AtlasPopulationMode.Static;Directory.CreateDirectory(Path.GetDirectoryName(dest));var atlases=a.atlasTextures;var material=a.material;AssetDatabase.CreateAsset(a,dest);foreach(var t in atlases){t.hideFlags=HideFlags.None;AssetDatabase.AddObjectToAsset(t,a);}material.hideFlags=HideFlags.None;AssetDatabase.AddObjectToAsset(material,a);a.atlasTextures=atlases;a.material=material;EditorUtility.SetDirty(a);AssetDatabase.SaveAssets();AssetDatabase.ImportAsset(dest,ImportAssetOptions.ForceSynchronousImport);var verify=AssetDatabase.LoadAssetAtPath<TMP_FontAsset>(dest);if(verify.material==null||verify.atlasTextures[0]==null)throw new InvalidOperationException("Font persistence failed:"+name);}
